head.script:
scwin.gVar = {
    "cID" : "target1"
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
//  - iframe 을 dynamicCreate 할 때 inline src 를 주면 _dynamicCreateAfter 가 미로딩 contentDocument 에 접근하여 TypeError 발생.
//    → src 없이 생성한 뒤 target1.setSrc() 로 내부 페이지를 설정한다. (reference_iframe_dynamic_setsrc_not_inline)
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof scwin.target1 !== 'undefined') {
        scwin.target1.remove();
    }

    // 조건 설정
    let cID = scwin.gVar["cID"];

    // comp 생성
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    // iframe 동적 생성 (inline src 금지, id 는 cID)
    strTarget += '<w2:iframe ' + strNameSpace + ' style="width:500px; height:300px; " id=""></w2:iframe>';

    // target 생성 (cID 가 빈 문자열이면 dynamicCreate 가 자동 id 부여)
    scwin.target1 = await $p.dynamicCreate(
        cID,
        "iframe",
        strTarget,
        grp_comp
    );

    // 내부 페이지 설정 (생성 후 setSrc)
    scwin.target1.setSrc("/sample/common_link/iframe_link_1.xml");
}
